(function() {
    'use strict';

    class LeaderAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Becoming a Leader`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // The concept's truth: the CEO threatened a provisional leadership identity, not the
            // task. Owning the miss is the only first move that does identity work.
            this.TRUE_THREAT = `identity`;
            this.TRUE_RESPONSE = `own`;

            // Company norm the recovery aims at; starting pulse after the setback.
            this.CONFIDENCE_NORM = 71;
            this.CONFIDENCE_START = 38;
            // The "held authentic" sweet spot on the 0..100 armour..disclosure spectrum.
            this.STANCE_LOW = 50;
            this.STANCE_HIGH = 70;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    confidence: 38,
                    identity: 30,
                    credibility: 40,
                    sustain: 20,
                    relationships: [],
                    relationshipCount: 0,
                    daysSpent: 0,
                    secondLeadGone: false,
                    confidenceHistory: [38],
                    identityHistory: [30],
                    credibilityHistory: [40],
                    sustainHistory: [20],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    threat: `identity`,
                    response: `own`,
                    candor: 55,
                    relationships: [],
                    ask: `hold`,
                    stance: 60,
                    leads: `ownask`,
                    reveal: `measured`,
                    purpose: `specific`,
                    roadmap: `bridge`,
                    horizon: `visible`,
                    conviction: 70
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const thr = document.getElementById(`threatInput`);
                const resp = document.getElementById(`responseInput`);
                const can = document.getElementById(`candorInput`);
                if (thr) decisions.threat = thr.value;
                if (resp) decisions.response = resp.value;
                if (can) decisions.candor = parseInt(can.value, 10);
                if (!Number.isFinite(decisions.candor) || decisions.candor < 0 || decisions.candor > 100) {
                    warn(`warn_candor_range`); return false;
                }
            } else if (round === 2) {
                const ids = [
                    [`relPeer`, `peer`], [`relSponsor`, `sponsor`],
                    [`relReport`, `report`], [`relCoach`, `coach`]
                ];
                const picked = [];
                ids.forEach(([elId, val]) => {
                    const el = document.getElementById(elId);
                    if (el && el.checked) picked.push(val);
                });
                decisions.relationships = picked;
                const ask = document.getElementById(`askInput`);
                if (ask) decisions.ask = ask.value;
                if (picked.length < 1) {
                    warn(`warn_rel_none`); return false;
                }
                if (picked.length > 2) {
                    warn(`warn_rel_many`); return false;
                }
            } else if (round === 3) {
                const st = document.getElementById(`stanceInput`);
                const ld = document.getElementById(`leadsInput`);
                const rv = document.getElementById(`revealInput`);
                if (st) decisions.stance = parseInt(st.value, 10);
                if (ld) decisions.leads = ld.value;
                if (rv) decisions.reveal = rv.value;
                if (!Number.isFinite(decisions.stance) || decisions.stance < 0 || decisions.stance > 100) {
                    warn(`warn_stance_range`); return false;
                }
            } else if (round === 4) {
                const pp = document.getElementById(`purposeInput`);
                const rm = document.getElementById(`roadmapInput`);
                const hz = document.getElementById(`horizonInput`);
                const cv = document.getElementById(`convictionInput`);
                if (pp) decisions.purpose = pp.value;
                if (rm) decisions.roadmap = rm.value;
                if (hz) decisions.horizon = hz.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let confDelta = 0, idDelta = 0, credDelta = 0, sustDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose the threat. Reading it as identity work (not a slide problem) is the
                // whole point; owning the miss is the only first move that builds rather than
                // erodes. Common Error 1: fixing the slides, not the self.
                if (d.threat === this.TRUE_THREAT) { idDelta += 16; credDelta += 4; coachKey = `coach_r1_threat_right`; }
                else if (d.threat === `task`) { idDelta -= 8; confDelta -= 2; coachKey = `coach_r1_threat_task`; }
                else { idDelta -= 4; coachKey = `coach_r1_threat_off`; }

                switch (d.response) {
                    case `own`:
                        confDelta += 8; credDelta += 10; idDelta += 6; sustDelta += 6;
                        coachKey = (d.threat === this.TRUE_THREAT) ? `coach_r1_own_sharp` : `coach_r1_own`; break;
                    case `defend`:
                        confDelta -= 4; credDelta -= 8; idDelta -= 2; coachKey = `coach_r1_defend`; break;
                    case `deflect`:
                        confDelta -= 6; credDelta -= 10; coachKey = `coach_r1_deflect`; break;
                    case `withdraw`:
                        confDelta -= 10; credDelta -= 6; idDelta -= 8; sustDelta -= 6;
                        ds.secondLeadGone = true; coachKey = `coach_r1_withdraw`; break;
                }

                // Candor = willingness to do identity work rather than hide in the spreadsheet.
                if (d.candor >= 60) { idDelta += 8; sustDelta += 4; }
                else if (d.candor <= 25) { idDelta -= 8; sustDelta -= 4; coachKey = `coach_r1_lowcandor`; }

                summaryKey = (d.threat === this.TRUE_THREAT && d.response === this.TRUE_RESPONSE) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Build a holding environment. Selectivity is the lesson: one or two who can
                // actually hold this. Common Error 4 (diffuse leaning) and the solo-heroics trap.
                const rels = d.relationships || [];
                ds.relationships = rels.slice();
                ds.relationshipCount = rels.length;
                // Roughly two days of trust/time per relationship genuinely opened.
                ds.daysSpent = rels.length * 2;

                const REL_ID = { peer: 6, sponsor: 4, report: 7, coach: 8 };
                const REL_CRED = { peer: 2, sponsor: 9, report: 5, coach: 3 };
                const REL_SUST = { peer: 7, sponsor: 2, report: 6, coach: 9 };
                rels.forEach((r) => {
                    idDelta += (REL_ID[r] || 0);
                    credDelta += (REL_CRED[r] || 0);
                    sustDelta += (REL_SUST[r] || 0);
                });

                if (rels.length === 0) {
                    // Should be blocked by validation, but the solo path is the real threat.
                    idDelta -= 12; sustDelta -= 12; coachKey = `coach_r2_solo`;
                } else if (rels.length === 1) {
                    idDelta += 6; sustDelta += 4; coachKey = `coach_r2_one`;
                } else if (rels.length === 2) {
                    idDelta += 10; sustDelta += 8; credDelta += 3; coachKey = `coach_r2_two`;
                }

                // Leaning ONLY on the sponsor clings to the old expert identity (provisional-selves trap).
                if (rels.length === 1 && rels[0] === `sponsor`) {
                    idDelta -= 6; sustDelta -= 4; coachKey = `coach_r2_sponsoronly`;
                }
                // A holding environment that includes a peer or coach gives real containment.
                const hasHolder = rels.indexOf(`peer`) !== -1 || rels.indexOf(`coach`) !== -1;
                if (!hasHolder && rels.length > 0) { sustDelta -= 4; }

                // The ask matters: being HELD (vs reassured/rescued) is the developmental move.
                switch (d.ask) {
                    case `hold`:
                        idDelta += 8; sustDelta += 8; confDelta += 4; coachKey = `coach_r2_ask_hold`; break;
                    case `advice`:
                        credDelta += 4; idDelta += 2; coachKey = `coach_r2_ask_advice`; break;
                    case `reassure`:
                        idDelta -= 4; sustDelta -= 4; coachKey = `coach_r2_ask_reassure`; break;
                    case `rescue`:
                        credDelta -= 8; idDelta -= 6; coachKey = `coach_r2_ask_rescue`; break;
                }

                summaryKey = (rels.length >= 1 && rels.length <= 2 && d.ask === `hold` && hasHolder) ? `sum_r2_good` : `sum_r2_weak`;
            } else if (round === 3) {
                // Take a stance. Armour (low) = false certainty the room sees through; collapse
                // (high) = contagious doubt. The held authentic band is ~50-70. Common Errors 2 & 3.
                const s = d.stance;
                if (s < this.STANCE_LOW) {
                    // Armouring up.
                    const dist = this.STANCE_LOW - s;
                    confDelta -= Math.round(dist / 5) + 2;
                    credDelta -= Math.round(dist / 6) + 2;
                    idDelta -= 4; sustDelta -= 6;
                    coachKey = `coach_r3_armour`;
                } else if (s > this.STANCE_HIGH) {
                    // Collapsing into disclosure — contagion.
                    const dist = s - this.STANCE_HIGH;
                    confDelta -= Math.round(dist / 4) + 3;
                    credDelta -= Math.round(dist / 8);
                    idDelta -= 2; sustDelta -= 2;
                    coachKey = `coach_r3_collapse`;
                } else {
                    // Held authentic stance: congruence between values, identity and action.
                    confDelta += 12; credDelta += 8; idDelta += 10; sustDelta += 10;
                    coachKey = `coach_r3_held`;
                }

                // The opening line to the two departing leads.
                switch (d.leads) {
                    case `ownask`:
                        confDelta += 8; credDelta += 8; idDelta += 6; sustDelta += 4;
                        coachKey = (s >= this.STANCE_LOW && s <= this.STANCE_HIGH) ? `coach_r3_ownask_sharp` : coachKey; break;
                    case `command`:
                        confDelta -= 8; credDelta -= 10; sustDelta -= 6;
                        ds.secondLeadGone = true; coachKey = `coach_r3_command`; break;
                    case `confess`:
                        confDelta -= 12; idDelta -= 4; sustDelta -= 4;
                        coachKey = `coach_r3_confess`; break;
                    case `transactional`:
                        credDelta -= 12; sustDelta -= 8; idDelta -= 4;
                        coachKey = `coach_r3_transactional`; break;
                }

                // What she reveals about her own doubt.
                if (d.reveal === `measured`) { idDelta += 8; sustDelta += 6; confDelta += 4; }
                else if (d.reveal === `none`) { idDelta -= 6; sustDelta -= 8; credDelta += 2; coachKey = (s < this.STANCE_LOW) ? coachKey : `coach_r3_reveal_none`; }
                else if (d.reveal === `all`) { confDelta -= 8; sustDelta -= 4; coachKey = (s > this.STANCE_HIGH) ? coachKey : `coach_r3_reveal_all`; }

                summaryKey = (s >= this.STANCE_LOW && s <= this.STANCE_HIGH && d.leads === `ownask` && d.reveal === `measured`) ? `sum_r3_good` : `sum_r3_weak`;
            } else if (round === 4) {
                // Set the purpose. A specific, honest purpose survives the next setback; a slogan
                // gives no guidance. Common Error 5. The roadmap reframe and recovery plan land
                // the transformation. Conviction that a held identity (not performed certainty)
                // is leadership nudges sustainability.
                switch (d.purpose) {
                    case `specific`:
                        sustDelta += 18; idDelta += 12; confDelta += 6; credDelta += 6; coachKey = `coach_r4_specific`; break;
                    case `slogan`:
                        sustDelta -= 10; idDelta -= 2; coachKey = `coach_r4_slogan`; break;
                    case `expert`:
                        sustDelta -= 6; idDelta -= 8; credDelta -= 4; coachKey = `coach_r4_expert`; break;
                    case `results`:
                        sustDelta -= 8; idDelta -= 4; coachKey = `coach_r4_results`; break;
                }

                switch (d.roadmap) {
                    case `bridge`:
                        credDelta += 12; confDelta += 8; sustDelta += 4; coachKey = (d.purpose === `specific`) ? `coach_r4_bridge_sharp` : `coach_r4_bridge`; break;
                    case `polish`:
                        credDelta -= 6; confDelta -= 4; coachKey = `coach_r4_polish`; break;
                    case `capitulate`:
                        credDelta += 2; idDelta -= 10; sustDelta -= 8; coachKey = `coach_r4_capitulate`; break;
                }

                switch (d.horizon) {
                    case `visible`:
                        confDelta += 12; sustDelta += 6; credDelta += 4; break;
                    case `grand`:
                        confDelta += 2; sustDelta -= 6; coachKey = (d.purpose === `slogan`) ? coachKey : `coach_r4_grand`; break;
                    case `quiet`:
                        confDelta -= 6; sustDelta -= 4; coachKey = `coach_r4_quiet`; break;
                }

                // Conviction that a held, honest identity (not armour) is leadership.
                sustDelta += Math.round((d.conviction - 60) / 8);

                summaryKey = (d.purpose === `specific` && d.roadmap === `bridge` && d.horizon === `visible`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // A second team lead leaving costs confidence (~25 of 240 destabilised).
            if (ds.secondLeadGone && round <= 3) {
                confDelta -= 4;
            }

            // Apply deltas with clamps. Confidence is a percentage toward the 71% norm.
            ds.confidence = Math.max(0, Math.min(100, ds.confidence + confDelta));
            ds.identity = Math.max(0, Math.min(100, ds.identity + idDelta));
            ds.credibility = Math.max(0, Math.min(100, ds.credibility + credDelta));
            ds.sustain = Math.max(0, Math.min(100, ds.sustain + sustDelta));

            ds.confidenceHistory.push(Math.round(ds.confidence));
            ds.identityHistory.push(Math.round(ds.identity));
            ds.credibilityHistory.push(Math.round(ds.credibility));
            ds.sustainHistory.push(Math.round(ds.sustain));

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            var res = {
                period: state.currentPeriod,
                confidence: Math.round(ds.confidence),
                confidenceDelta: Math.round(confDelta),
                identity: Math.round(ds.identity),
                identityDelta: Math.round(idDelta),
                credibility: Math.round(ds.credibility),
                credibilityDelta: Math.round(credDelta),
                sustain: Math.round(ds.sustain),
                sustainDelta: Math.round(sustDelta),
                secondLeadGone: ds.secondLeadGone,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
            // Expose composite to the reporting/grading layer each period (results_utils.php reads
            // domainState.performance.overallScore); period 4 locks the authoritative score.
            ds.performance = { overallScore: this._composite(ds) };
            return res;
        }

