        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.confidenceHistory.map((_, i) => (i === 0 ? `Start` : `R` + i));
            return {
                leaderChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.confidenceHistory },
                        { data: ds.identityHistory },
                        { data: ds.credibilityHistory },
                        { data: ds.sustainHistory }
                    ]
                }
            };
