        // Shared composite (0-100). Single source of truth for the per-period score written to
        // domainState.performance.overallScore (reporting/grading layer) AND the debrief. Weights
        // identical to v1.0.0.
        _composite(ds) {
            var confidence = Math.round(ds.confidence || 0), identity = Math.round(ds.identity || 0);
            var credibility = Math.round(ds.credibility || 0), sustain = Math.round(ds.sustain || 0);
            return Math.max(0, Math.min(100, Math.round(confidence * 0.3 + identity * 0.25 + credibility * 0.2 + sustain * 0.25)));
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const confidence = Math.round(ds.confidence);
            const identity = Math.round(ds.identity);
            const credibility = Math.round(ds.credibility);
            const sustain = Math.round(ds.sustain);

            // The mandate: recover confidence toward the 71% norm AND hold a sustainable,
            // integrated leadership identity (not performed authority).
            const recovered = confidence >= 65;
            const integrated = identity >= 60 && sustain >= 60;
            const composite = this._composite(ds);

            const T = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? function(k, v) { return window.mySimulation.t(k, v); }
                : function(k) { return k; };

            // Grade band -> localized label (thresholds identical to v1.0.0).
            let performanceKey = `grade_impostor`;
            if (recovered && integrated && credibility >= 60 && composite >= 70) performanceKey = `grade_becoming`;
            else if (recovered && sustain >= 55 && composite >= 60) performanceKey = `grade_recovery`;
            else if (confidence >= 50 && composite >= 48) performanceKey = `grade_surface`;
            else if (sustain < 35) performanceKey = `grade_performed`;
            const performance = T(performanceKey);

            const insights = [];
            if (recovered && integrated && credibility >= 60) insights.push(window.mySimulation.t(`insight_becoming`));
            else if (confidence >= 55 && sustain < 45) insights.push(window.mySimulation.t(`insight_armour`));
            else if (sustain < 35) insights.push(window.mySimulation.t(`insight_fragile`));
            else insights.push(window.mySimulation.t(`insight_partial`));

            if (sustain < 45) insights.push(window.mySimulation.t(`insight_slogan`));
            if (identity < 45) insights.push(window.mySimulation.t(`insight_lowidentity`));
            if (ds.relationshipCount === 0) insights.push(window.mySimulation.t(`insight_solo`));
            if (ds.secondLeadGone) insights.push(window.mySimulation.t(`insight_leadgone`));
            if (recovered && integrated && credibility >= 60) insights.push(window.mySimulation.t(`insight_held`));

            return {
                confidence: confidence,
                identity: identity,
                credibility: credibility,
                sustain: sustain,
                recovered: recovered,
                integrated: integrated,
                composite: composite,
                totalScore: composite,
                overallScore: composite,
                performanceKey: performanceKey,
                performance: performance,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            var T = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? function(k, v) { return window.mySimulation.t(k, v); }
                : function(k) { return k; };
            var s = summary || {};
            var score = (typeof s.totalScore === 'number') ? s.totalScore
                : (typeof s.composite === 'number' ? s.composite : 0);
            var grade = s.performance || (s.performanceKey ? T(s.performanceKey) : '');
            var rec = !!s.recovered;
            var badge = rec
                ? '<span class="bl-cm-badge bl-cm-yes">' + T('cm_recovered') + '</span>'
                : '<span class="bl-cm-badge bl-cm-no">' + T('cm_notrecovered') + '</span>';
            var insights = Array.isArray(s.insights) ? s.insights : [];
            var items = insights.map(function(t) { return '<li>' + t + '</li>'; }).join('');
            var metrics = ''
                + '<div class="bl-cm-metric"><span class="bl-cm-mv">' + Math.round(s.confidence||0) + '</span><span class="bl-cm-ml">' + T('cm_m_conf') + '</span></div>'
                + '<div class="bl-cm-metric"><span class="bl-cm-mv">' + Math.round(s.identity||0) + '</span><span class="bl-cm-ml">' + T('cm_m_identity') + '</span></div>'
                + '<div class="bl-cm-metric"><span class="bl-cm-mv">' + Math.round(s.credibility||0) + '</span><span class="bl-cm-ml">' + T('cm_m_cred') + '</span></div>'
                + '<div class="bl-cm-metric"><span class="bl-cm-mv">' + Math.round(s.sustain||0) + '</span><span class="bl-cm-ml">' + T('cm_m_sustain') + '</span></div>';
            return ''
                + '<div class="bl-completion">'
                +   '<div class="bl-cm-head">'
                +     '<div class="bl-cm-score">' + score + '<span class="bl-cm-score-max">/100</span></div>'
                +     '<div class="bl-cm-grade">' + grade + ' ' + badge + '</div>'
                +   '</div>'
                +   '<div class="bl-cm-metrics">' + metrics + '</div>'
                +   '<div class="bl-cm-insights-title">' + T('cm_debrief') + '</div>'
                +   '<ul class="bl-cm-insights">' + items + '</ul>'
                + '</div>';
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.confidence < 35) return window.mySimulation.t(`hint_confidence`);
            if (ds.sustain < 30 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_sustain`);
            if (ds.identity < 35 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_identity`);
            if (ds.relationshipCount === 0 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_solo`);
            if (ds.confidence >= 60 && ds.identity >= 55 && ds.sustain >= 55) return window.mySimulation.t(`hint_strong`);
            return null;
        }

